import { test, expect } from '@playwright/test';

test.describe('Colour Contrast WCAG 2.1 AA Compliance', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/page');
  });

  test('should display all text with WCAG AA compliant colour contrast', async ({ page }) => {
    // Verify main heading has sufficient contrast
    const mainHeading = page.getByRole('heading', { name: /main content/i });
    await expect(mainHeading).toBeVisible();

    // Verify main heading text colour is dark enough
    const headingText = page.locator('[data-testid="heading-text"]');
    await expect(headingText).toHaveCSS('color', /#000000|#333333/);

    // Verify background has sufficient contrast
    const background = page.locator('[data-testid="page-background"]');
    await expect(background).toHaveCSS('background-color', /#ffffff|#f5f8fa/);

    // Verify body text has sufficient contrast against background
    const bodyText = page.getByText(/this is body text/i);
    await expect(bodyText).toBeVisible();

    // Verify body text colour is dark enough
    await expect(bodyText).toHaveCSS('color', /#000000|#333333/);

    // Verify body text background has sufficient contrast
    await expect(bodyText).toHaveCSS('background-color', /#ffffff|#f5f8fa/);

    // Verify secondary text (e.g., captions) has sufficient contrast
    const secondaryText = page.getByText(/secondary information/i);
    await expect(secondaryText).toBeVisible();

    // Verify secondary text colour is dark enough
    await expect(secondaryText).toHaveCSS('color', /#333333|#000000/);

    // Verify secondary text background has sufficient contrast
    await expect(secondaryText).toHaveCSS('background-color', /#ffffff|#f5f8fa/);

    // Verify links have sufficient contrast
    const link = page.getByRole('link', { name: /read more/i });
    await expect(link).toBeVisible();

    // Verify link text colour is dark enough
    await expect(link).toHaveCSS('color', /#000000|#333333/);

    // Verify link background has sufficient contrast
    await expect(link).toHaveCSS('background-color', /transparent|none/);
  });

  test('should fail contrast check when using low-contrast colours', async ({ page }) => {
    // Navigate to a page with low contrast colours
    await page.goto('/low-contrast-page');

    // Verify low contrast heading is visible
    const lowContrastHeading = page.getByRole('heading', { name: /low contrast example/i });
    await expect(lowContrastHeading).toBeVisible();

    // Verify low contrast text colour is light grey
    const lowContrastText = page.locator('[data-testid="low-contrast-text"]');
    await expect(lowContrastText).toHaveCSS('color', /#aaaaaa|#cccccc/);

    // Verify low contrast background is light grey
    const lowContrastBackground = page.locator('[data-testid="low-contrast-background"]');
    await expect(lowContrastBackground).toHaveCSS('background-color', /#f0f0f0|#eeeeee/);

    // Verify low contrast body text is visible
    const lowContrastBody = page.getByText(/this text has low contrast/i);
    await expect(lowContrastBody).toBeVisible();

    // Verify low contrast body text colour is light grey
    await expect(lowContrastBody).toHaveCSS('color', /#aaaaaa|#cccccc/);

    // Verify low contrast background is light grey
    await expect(lowContrastBody).toHaveCSS('background-color', /#f0f0f0|#eeeeee/);

    // Verify contrast warning message appears
    const contrastWarning = page.getByText(/colour contrast does not meet WCAG AA standards/i);
    await expect(contrastWarning).toBeVisible();

    // Verify warning has appropriate contrast
    await expect(contrastWarning).toHaveCSS('color', /#000000|#333333/);
    await expect(contrastWarning).toHaveCSS('background-color', /#ffffff|#f5f8fa/);
  });
});
